const inputData = $('Execute Workflow Trigger').first().json;
const cb = inputData.callback_data || '';
const menuItems = $input.all().map(i => i.json);

if (cb === 'cat_ver_todas' || cb === 'back_menu') {
  const categories = [...new Set(menuItems.filter(i => parseInt(i.stock) > 0).map(i => i.categoria))].filter(Boolean);
  const keyboard = categories.map(cat => ([{ text: '\u{1F4C1} ' + cat, callback_data: 'cat_' + cat }]));
  keyboard.push([{ text: '\u2B05\uFE0F Volver al Inicio', callback_data: 'main_menu' }]);
  return [{
    json: {
      mensaje: '\u{1F6D2} *Categor\u00edas*\\n\\nSelecciona una categor\u00eda:',
      reply_markup: { inline_keyboard: keyboard },
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: inputData.carrito_json || '[]', contexto_json: inputData.contexto_json || '{}' }
    }
  }];
}

if (cb.startsWith('cat_') && cb !== 'cat_ver_todas') {
  const category = cb.replace('cat_', '');
  const items = menuItems.filter(i => i.categoria === category && parseInt(i.stock) > 0);
  const keyboard = items.map(item => ([{ text: '\u2795 ' + item.nombre + ' ($' + item.precio + ')', callback_data: 'add_' + item.id_producto }]));
  keyboard.push([{ text: '\u{1F6D2} Ver Carrito', callback_data: 'view_cart' }]);
  keyboard.push([{ text: '\u2B05\uFE0F Categor\u00edas', callback_data: 'cat_ver_todas' }]);
  return [{
    json: {
      mensaje: '\u{1F4C1} *' + category + '*\\n\\nSelecciona un producto:',
      reply_markup: { inline_keyboard: keyboard },
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: inputData.carrito_json || '[]', contexto_json: JSON.stringify({ current_category: category }) }
    }
  }];
}

if (cb.startsWith('add_')) {
  const productId = cb.replace('add_', '');
  const product = menuItems.find(i => i.id_producto === productId);
  let cart = [];
  try { cart = JSON.parse(inputData.carrito_json || '[]'); } catch(e) {}
  if (product) {
    const existing = cart.find(i => i.id === productId);
    if (existing) { existing.qty += 1; }
    else { cart.push({ id: productId, nombre: product.nombre, precio: parseFloat(product.precio), qty: 1 }); }
  }
  let ctx = {};
  try { ctx = JSON.parse(inputData.contexto_json || '{}'); } catch(e) {}
  return [{
    json: {
      mensaje: '\u2705 ' + (product ? product.nombre : 'Producto') + ' agregado al carrito.',
      reply_markup: { inline_keyboard: [
        [{ text: '\u2B05\uFE0F Seguir comprando', callback_data: ctx.current_category ? 'cat_' + ctx.current_category : 'cat_ver_todas' }],
        [{ text: '\u{1F6D2} Ver Carrito', callback_data: 'view_cart' }]
      ]},
      session_updates: { estado_fsm: 'SELECCION_CANTIDAD', carrito_json: JSON.stringify(cart), contexto_json: inputData.contexto_json || '{}' }
    }
  }];
}

if (cb === 'confirm_track') {
  return [{
    json: {
      mensaje: '\u{1F4CD} *Seguimiento*\\n\\nPor favor, ingresa tu n\u00famero de orden (ej: ORD-1234):',
      reply_markup: { inline_keyboard: [[{ text: '\u2B05\uFE0F Volver', callback_data: 'main_menu' }]] },
      session_updates: { estado_fsm: 'TRACK_ORDER', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
    }
  }];
}

if (cb === 'cart_ver_historial') {
  return [{
    json: {
      mensaje: '\u{1F4CB} *Mis Pedidos*\\n\\nNo tienes pedidos recientes.',
      reply_markup: { inline_keyboard: [[{ text: '\u2B05\uFE0F Volver', callback_data: 'main_menu' }]] },
      session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: inputData.carrito_json || '[]', contexto_json: '{}' }
    }
  }];
}

return [{
  json: {
    mensaje: '\u00a1Bienvenido a DeliveryBot! \u{1F354}\\n\\nPor favor, selecciona una opci\u00f3n:',
    reply_markup: { inline_keyboard: [
      [{ text: '\u{1F6D2} Hacer Pedido', callback_data: 'cat_ver_todas' }],
      [{ text: '\u{1F4CB} Mis Pedidos', callback_data: 'cart_ver_historial' }, { text: '\u{1F4CD} Seguir Pedido', callback_data: 'confirm_track' }]
    ]},
    session_updates: { estado_fsm: 'MENU_PRINCIPAL', carrito_json: '[]', contexto_json: '{}' }
  }
}];
